css:
.d-ct{width:300px;max-width:100%;height:150px;padding:12px;border:1px solid var(--line);border-radius:2px;background:var(--bg);font-family:var(--sans)}
.d-ct-card{padding:7px 10px;border:1px solid var(--line);border-radius:2px;background:var(--paper);box-shadow:0 1px 0 var(--line)}
.d-ct-h{display:block;font-size:11px;line-height:1.5;font-weight:650;color:var(--ink)}
.d-ct-p{margin:4px 0 0;font-size:11px;line-height:1.6;color:var(--muted)}
.d-ct-meta{display:block;margin-top:6px;font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--faint)}
.d-ct-bar{display:flex;align-items:center;gap:10px;margin-top:10px}
.d-ct-sw{display:inline-flex;align-items:center;gap:6px;padding:3px 8px 3px 4px;border:1px solid var(--line);border-radius:999px;background:var(--paper);cursor:pointer}
.d-ct-sw:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-ct-track{display:block;width:32px;height:16px;padding:1px;border:1px solid var(--line);border-radius:999px;background:var(--bg)}
.d-ct-knob{display:block;width:12px;height:12px;border-radius:999px;background:var(--faint);transform:translateX(0);transition:transform 120ms steps(6),background-color 120ms steps(6)}
.d-ct-opt{font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--muted)}
.d-ct-state{font-family:var(--mono);font-size:9px;letter-spacing:.06em;color:var(--faint)}
.d-ct.is-hc{background:var(--paper)}
.d-ct.is-hc .d-ct-card{box-shadow:none;border-color:var(--ink)}
.d-ct.is-hc .d-ct-p{color:var(--ink)}
.d-ct.is-hc .d-ct-meta{color:var(--muted)}
.d-ct.is-hc .d-ct-track{border-color:var(--ink);background:var(--paper)}
.d-ct.is-hc .d-ct-opt,.d-ct.is-hc .d-ct-state{color:var(--ink)}
.d-ct.is-hc .d-ct-knob{transform:translateX(16px);background:var(--ink)}

init:
root => {
  const box = root.querySelector('.d-ct');
  if (!box || box.dataset.ct) return;
  box.dataset.ct = '1';
  const sw = box.querySelector('.d-ct-sw');
  const state = box.querySelector('.d-ct-state');
  const paint = on => {
    box.classList.toggle('is-hc', on);
    sw.classList.toggle('is-on', on);
    sw.setAttribute('aria-checked', String(on));
    state.textContent = on ? 'STATE · 高对比' : 'STATE · 正常';
  };
  sw.addEventListener('click', () => paint(sw.getAttribute('aria-checked') !== 'true'));
  paint(false);
}
